#!/usr/bin/env bash
#
# Run every benchmark layer once and drop the raw output in one directory.
#
#   benchmarks/run_all.sh <label> <output-dir> <synthetic-repos-dir>
#
# `label` goes into the harness JSON so two runs can be told apart. The
# synthetic repos directory is expected to already contain cc-small/cc-medium/
# cc-large, generated by:
#
#   for p in small medium large; do
#     python3 benchmarks/gen_repo.py --preset $p --out "$REPOS/cc-$p" --force
#   done
#
# The point of this script is that the SAME commands run on both sides of a
# comparison. Anything conditional or interactive belongs somewhere else.
#
# Criterion is invoked with explicit, uniform sampling parameters (rather than
# each group's own defaults) so the two runs sample identically regardless of
# what the bench files ask for.

set -euo pipefail

if [ $# -lt 3 ]; then
  echo "usage: $0 <label> <output-dir> <synthetic-repos-dir>" >&2
  exit 2
fi

LABEL="$1"
OUT="$(mkdir -p "$2" && cd "$2" && pwd)"
REPOS="$3"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

CRITERION_ARGS=(--warm-up-time 1 --measurement-time 3 --sample-size 20)

echo "== [$LABEL] building release harness =="
cargo build --release --example perf_harness -p cc-core --manifest-path "$ROOT/Cargo.toml"

HARNESS="$ROOT/target/release/examples/perf_harness"

for size in small medium large; do
  repo="$REPOS/cc-$size"
  if [ ! -d "$repo" ]; then
    echo "-- skipping $size: $repo does not exist" >&2
    continue
  fi
  echo "== [$LABEL] harness on synthetic $size =="
  "$HARNESS" --repo "$repo" --label "$LABEL/$size" --out "$OUT/harness-$size.json" \
    > /dev/null 2> "$OUT/harness-$size.log"
done

echo "== [$LABEL] harness on the CodeCartographer repo itself =="
"$HARNESS" --repo "$ROOT" --label "$LABEL/self" --out "$OUT/harness-self.json" \
  > /dev/null 2> "$OUT/harness-self.log"

echo "== [$LABEL] criterion =="
(cd "$ROOT" && cargo bench -p cc-core -- "${CRITERION_ARGS[@]}") \
  > "$OUT/criterion.txt" 2>&1 || echo "criterion exited non-zero; see $OUT/criterion.txt" >&2

echo "== [$LABEL] frontend edge routing =="
if [ -d "$ROOT/packages/app/node_modules" ]; then
  (cd "$ROOT/packages/app" && node benchmarks/edgeRouting.bench.ts \
      --label "$LABEL" --json "$OUT/edge-routing.json") \
    > /dev/null 2> "$OUT/edge-routing.log"
else
  echo "-- skipping frontend bench: run pnpm install in packages/app first" >&2
fi

echo "== [$LABEL] done: $OUT =="
